CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), applicant_id uuid NOT NULL REFERENCES applicants(id) ON DELETE CASCADE, amount_kes integer NOT NULL CHECK (amount_kes > 0), phone text NOT NULL, status text NOT NULL DEFAULT 'pending', merchant_request_id text, checkout_request_id text UNIQUE, mpesa_receipt_number text UNIQUE, result_code integer, result_desc text, requested_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, raw_callback jsonb)